#!/bin/bash
set -e
V1_TAG=pre-promote-demote-uxfix-20260518-q1ack
V2_TAG=pre-promote-demote-uxfix-20260518-v2
BASE=/home/azureuser/trading_corp
PY=$BASE/venv/bin/python
cd $BASE

# 1. Snapshot CURRENT (v1-applied) state under v2 tag — so we can roll back to v1 if v2 breaks.
cp trading_corp/web/routes.py trading_corp/web/routes.py.$V2_TAG
cp trading_corp/web/data.py   trading_corp/web/data.py.$V2_TAG
cp trading_corp/web/templates/prediction_markets_dashboard.html trading_corp/web/templates/prediction_markets_dashboard.html.$V2_TAG 2>/dev/null || true

# 2. Restore from pre-v1 backup so v2 patch (which is local-HEAD vs local-current) applies cleanly.
cp trading_corp/web/routes.py.$V1_TAG trading_corp/web/routes.py
cp trading_corp/web/data.py.$V1_TAG   trading_corp/web/data.py

# (dashboard.html had no v1 changes — no backup tag for it. Current prod state IS the local-HEAD state for that file.)

# 3. CRLF normalize before patch
sed -i 's/\r$//' trading_corp/web/routes.py
sed -i 's/\r$//' trading_corp/web/data.py
sed -i 's/\r$//' trading_corp/web/templates/prediction_markets_dashboard.html

# 4. Apply combined v1+v2 patch
echo "" | base64 -d | gunzip > /tmp/uxfix_v2.patch
patch --dry-run -p1 < /tmp/uxfix_v2.patch
patch -p1 < /tmp/uxfix_v2.patch

# 5. md5 confirm
md5sum trading_corp/web/routes.py trading_corp/web/data.py trading_corp/web/templates/prediction_markets_dashboard.html

# 6. Import smoke
$PY -c "
from trading_corp.web import routes, data
from trading_corp.web.data import _query_pm_whales, _query_kalshi_watch_only_rows, _query_polymarket_watch_only_rows
import inspect
src = inspect.getsource(_query_pm_whales)
assert 'kalshi_selected' in src and 'pm_selected_user_names' in src, 'Selected filter missing'
src2 = inspect.getsource(_query_kalshi_watch_only_rows)
assert 'selected_set' in src2, 'Kalshi watch-only selected filter missing'
src3 = inspect.getsource(_query_polymarket_watch_only_rows)
assert 'selected_wallets' in src3, 'PM watch-only selected filter missing'
print('all filters present in source')
"

echo "===== Pre-restart PID ====="
systemctl show trading-corp -p MainPID --no-pager

# 7. Restart
sudo systemctl restart trading-corp
sleep 5

echo "===== Post-restart ====="
systemctl is-active trading-corp
systemctl show trading-corp -p MainPID --no-pager

echo "DEPLOY OK"
